import unittest
from candidate import below_threshold

class TestBelowThreshold(unittest.TestCase):
    def test_below_threshold_all_below(self):
        self.assertTrue(below_threshold([1, 2, 4, 10], 100))

    def test_below_threshold_one_above(self):
        self.assertFalse(below_threshold([1, 20, 4, 10], 5))

    def test_below_threshold_empty_list(self):
        self.assertTrue(below_threshold([], 100))

    def test_below_threshold_threshold_zero(self):
        self.assertFalse(below_threshold([1, 2, 4, 10], 0))

    def test_below_threshold_threshold_negative(self):
        self.assertTrue(below_threshold([1, 2, 4, 10], -100))

    def test_below_threshold_list_none(self):
        with self.assertRaises(TypeError):
            below_threshold(None, 100)

    def test_below_threshold_threshold_none(self):
        with self.assertRaises(TypeError):
            below_threshold([1, 2, 4, 10], None)

    def test_below_threshold_list_not_iterable(self):
        with self.assertRaises(TypeError):
            below_threshold('123', 100)

    def test_below_threshold_list_contains_non_int(self):
        with self.assertRaises(TypeError):
            below_threshold([1, 2, '4', 10], 100)

if __name__ == '__main__':
    unittest.main()
